WITH unpacked AS (SELECT id, service, host, level, latency_ms, status_code, payload_json, context, context['region'] AS region, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec FROM app_logs) SELECT *, RANK() OVER (ORDER BY status_code DESC) AS status_code_rank, ROW_NUMBER() OVER (ORDER BY status_code DESC, id ASC) AS event_seq FROM unpacked;
